    // @port: Daqifi.Desktop.Logger.LoggingManager.UpdateProfileInXml
    /// <summary>
    /// Writes an edited profile back to the file.
    /// </summary>
    /// <returns><c>true</c> when the edit reached disk.</returns>
    /// <remarks>
    /// Upstream edits the existing element field by field and gives up when the profile is not in
    /// the file. This replaces the element wholesale, and ADDS it when it is missing, for two
    /// reasons. Upstream's version silently dropped every device edit whenever the element had no
    /// <c>&lt;Devices&gt;</c> child, because <c>devicesElement?.RemoveAll()</c> and
    /// <c>devicesElement?.Add(...)</c> both no-op on a null. And once a damaged file has been
    /// quarantined the file is empty while the pane still holds the user's profiles, so "not in
    /// the file" is a state the app has to write its way out of rather than refuse for ever —
    /// which is the whole complaint in #184.
    /// </remarks>
    public bool UpdateProfileInXml(Profile profile)
    {
        try
        {
            var doc = _profileStore.Open();
            var updated = BuildProfileElement(profile);
            var existing = FindProfileElement(doc, profile.ProfileId);

            if (existing != null)
            {
                existing.ReplaceWith(updated);
            }
            else
            {
                AppLogger.Warning($"Profile with ID {profile.ProfileId} was not in the profiles file; writing it back.");
                doc.Root?.Add(updated);
            }

            _profileStore.Save(doc);
            return true;
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, "Error updating profile in XML");
            return false;
        }
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.AddAndRemoveProfileXml
    /// <summary>
    /// Adds or removes a profile in the file. A null <paramref name="profile"/> only ensures the
    /// file exists — how startup creates it on a fresh install.
    /// </summary>
    /// <returns><c>true</c> when the file was written.</returns>
    /// <remarks>
    /// Diverges from upstream by reporting failure to the caller instead of swallowing it into a
    /// log line, and by no longer touching <see cref="SubscribedProfiles"/>: the removal used to
    /// happen here, BEFORE the save, so a failed write left the profile gone from the pane and
    /// still in the file, reappearing at the next launch (#184). The collection is the caller's
    /// business now, and it is updated only once the write has actually succeeded.
    /// </remarks>
    public bool AddAndRemoveProfileXml(Profile? profile, bool AddProfileFlag)
    {
        try
        {
            var doc = _profileStore.Open();

            if (profile != null)
            {
                if (AddProfileFlag)
                {
                    doc.Root?.Add(BuildProfileElement(profile));
                }
                else
                {
                    FindProfileElement(doc, profile.ProfileId)?.Remove();
                }
            }

            _profileStore.Save(doc);
            return true;
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, "Error Setting Selected profile");
            return false;
        }
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.LoadProfilesFromXml
    /// <summary>
    /// Replaces <see cref="SubscribedProfiles"/> with what the profiles file holds, and returns it.
    /// </summary>
    /// <remarks>
    /// The collection is NOT cleared up front. Upstream cleared it before attempting the load, so
    /// a file that failed to parse emptied the Profiles pane while the file on disk still held
    /// every profile — a load destroying state it never successfully replaced (#184). A failed
    /// load now leaves the pane exactly as it was, and the unreadable file has been moved aside so
    /// that saving works again.
    /// </remarks>
    public List<Profile> LoadProfilesFromXml()
    {
        if (!_profileStore.TryLoad(out var loadedProfiles))
        {
            return SubscribedProfiles.ToList();
        }

        SubscribedProfiles.Clear();
        foreach (var profile in loadedProfiles)
        {
            SubscribedProfiles.Add(profile);
        }

        return loadedProfiles;
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.UnsubscribeProfile
    /// <summary>
    /// Deletes a profile from the file and from <see cref="SubscribedProfiles"/>.
    /// </summary>
    /// <returns><c>true</c> when the profile is gone from both.</returns>
    public bool UnsubscribeProfile(Profile profile)
    {
        try
        {
            var subscribedProfile = SubscribedProfiles.FirstOrDefault(x => x.ProfileId == profile.ProfileId);
            if (subscribedProfile == null)
            {
                // Already not subscribed: nothing to do, and nothing failed.
                return true;
            }

            if (!AddAndRemoveProfileXml(subscribedProfile, false))
            {
                return false;
            }

            SubscribedProfiles.Remove(subscribedProfile);
            ClearChannelList();
            return true;
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, "Error Unsubscribe Profile");
            return false;
        }
    }

    /// <summary>
    /// Builds the <c>&lt;Profile&gt;</c> element written to the file.
    /// </summary>
    /// <remarks>
    /// ONE builder for both writers. They used to be separate and disagreed about the same file:
    /// the add path always emitted <c>&lt;Channels&gt;</c> and put <c>&lt;SamplingFrequency&gt;</c>
    /// after it, while the update path omitted <c>&lt;Channels&gt;</c> when no channel was active
    /// and ordered the two the other way round. The reader carried a comment explaining the
    /// difference; it now only has to explain the older files.
    /// </remarks>
    private static XElement BuildProfileElement(Profile profile) =>
        new("Profile",
            new XElement("Name", profile.Name),
            new XElement("ProfileID", profile.ProfileId),
            new XElement("CreatedOn", profile.CreatedOn),
            new XElement("Devices",
                from device in profile.Devices
                select new XElement("Device",
                    new XElement("DeviceName", device.DeviceName),
                    new XElement("DevicePartNumber", device.DevicePartName),
                    new XElement("MACAddress", device.MacAddress),
                    new XElement("DeviceSerialNo", device.DeviceSerialNo),
                    new XElement("Channels",
                        from channel in device.Channels
                        where channel.IsChannelActive
                        select new XElement("Channel",
                            new XElement("Name", channel.Name),
                            new XElement("Type", channel.Type),
                            new XElement("IsActive", channel.IsChannelActive)
                        )
                    ),
                    new XElement("SamplingFrequency", device.SamplingFrequency)
                )
            )
        );

    /// <summary>
    /// Finds a profile element by id, tolerating entries with no <c>&lt;ProfileID&gt;</c> at all —
    /// a cast to <c>Guid</c> throws on those, which would take out the whole operation over one
    /// damaged entry.
    /// </summary>
    private static XElement? FindProfileElement(XDocument document, Guid profileId) =>
        document.Descendants("Profile")
            .FirstOrDefault(p => (Guid?)p.Element("ProfileID") == profileId);

    #endregion

    #region Channel Subscription
    // @port: Daqifi.Desktop.Logger.LoggingManager.Subscribe
    public void Subscribe(IChannel channel)
    {
        lock (_subscribedChannelsSync)
        {
            var current = _subscribedChannels;

            if (current.Any(x => x.DeviceSerialNo == channel.DeviceSerialNo && x.Name == channel.Name))
            {
                return;
            }

            channel.IsActive = true;

            // Only attach streaming handlers if in Stream mode
            if (CurrentMode == LoggingMode.Stream)
            {
                channel.OnChannelUpdated += HandleChannelUpdate;
            }

            // Copy-on-write: publish a new immutable snapshot (AsReadOnly wraps the fresh list so a
            // caller cannot downcast the published value back to List and mutate it) instead of
            // Add-ing to the one a reader on the transport thread may be enumerating right now. See
            // SubscribedChannels' remarks.
            List<IChannel> updated = [.. current, channel];
            Volatile.Write(ref _subscribedChannels, updated.AsReadOnly());
        }

        // Raised outside the lock so a binding handler can never re-enter under it.
        OnPropertyChanged(nameof(SubscribedChannels));
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.Unsubscribe
    public void Unsubscribe(IChannel channel)
    {
        lock (_subscribedChannelsSync)
        {
            var current = _subscribedChannels;

            var subscribedChannel = current.FirstOrDefault(
                x => x.DeviceSerialNo == channel.DeviceSerialNo && x.Name == channel.Name && x.IsActive);

            if (subscribedChannel == null)
            {
                return;
            }

            subscribedChannel.IsActive = false;

            // Remove event handler if it's attached
            subscribedChannel.OnChannelUpdated -= HandleChannelUpdate;

            // Copy-on-write -- see SubscribedChannels' remarks. AsReadOnly so the published snapshot
            // cannot be downcast to List and mutated outside the lock.
            //
            // Remove by reference, not by value. The lookup above already resolved the exact
            // instance to drop, and List.Remove would re-match it with the default comparer --
            // which lands on AbstractChannel.Equals, and that compares Name only. Two devices
            // both expose "AI0", so a value-based removal drops whichever same-named channel
            // sits earliest in the list rather than the one that was just deactivated.
            var updated = new List<IChannel>(current);
            updated.RemoveAll(x => ReferenceEquals(x, subscribedChannel));
            Volatile.Write(ref _subscribedChannels, updated.AsReadOnly());
        }

        // Raised outside the lock so a binding handler can never re-enter under it.
        OnPropertyChanged(nameof(SubscribedChannels));
    }
    #endregion

    /// <summary>
    /// Builds <see cref="SessionDeviceMetadata"/> rows for every device that has
    /// at least one subscribed channel at the start of a logging session.
    /// </summary>
    /// <param name="sessionId">The id of the session being created.</param>
    /// <returns>One materialized metadata entry per distinct device serial number.</returns>
    /// <remarks>
    /// Snapshots <see cref="SubscribedChannels"/> and
    /// <see cref="ConnectionManager.ConnectedDevices"/> up front so the result is
    /// computed against stable copies — these collections can otherwise mutate
    /// concurrently (e.g., from device-connection background threads) and throw
    /// during enumeration. Returns a fully materialized list rather than yielding
    /// lazily so the caller is never iterating against the live collections.
    /// Uses <see cref="StringComparer.Ordinal"/> for serial-number deduplication
    /// because device serials are opaque identifiers, not culture-sensitive text.
    /// </remarks>
    // @port: Daqifi.Desktop.Logger.LoggingManager.BuildDeviceMetadataForSession
    private List<SessionDeviceMetadata> BuildDeviceMetadataForSession(int sessionId)
    {
        var result = new List<SessionDeviceMetadata>();

        // Snapshot inputs before iterating to avoid concurrent-modification
        // exceptions on the underlying mutable lists.
        var subscribedChannelsSnapshot = SubscribedChannels?.ToList() ?? new List<IChannel>();
        var connectedDevicesSnapshot = ConnectionManager.Instance.ConnectedDevices?.ToList()
            ?? new List<IStreamingDevice>();

        var subscribedSerials = subscribedChannelsSnapshot
            .Select(c => c.DeviceSerialNo)
            .Where(s => !string.IsNullOrEmpty(s))
            .ToHashSet(StringComparer.Ordinal);

        if (subscribedSerials.Count == 0)
        {
            return result;
        }

        var emittedSerials = new HashSet<string>(StringComparer.Ordinal);

        foreach (var device in connectedDevicesSnapshot)
        {
            if (device == null || string.IsNullOrEmpty(device.DeviceSerialNo))
            {
                continue;
            }

            if (!subscribedSerials.Contains(device.DeviceSerialNo))
            {
                continue;
            }

            // Defensive: ConnectedDevices can briefly contain two entries with the
            // same serial (e.g., during USB re-enumeration). The composite primary
            // key on (LoggingSessionID, DeviceSerialNo) would otherwise reject the
            // second row and abort the session start.
            if (!emittedSerials.Add(device.DeviceSerialNo))
            {
                continue;
            }

            result.Add(new SessionDeviceMetadata
            {
                LoggingSessionID = sessionId,
                DeviceSerialNo = device.DeviceSerialNo,
                DeviceName = device.Name ?? string.Empty,
                SamplingFrequencyHz = device.StreamingFrequency
            });
        }

        return result;
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.HandleDeviceMessage
    public void HandleDeviceMessage(object sender, DeviceMessage sample)
    {
        if (!Active || CurrentMode != LoggingMode.Stream || !_hasActiveApplicationSession)
        {
            return;
        }

        sample.LoggingSessionID = Session.ID;

        //Log channel value to whatever loggers are being managed
        foreach (var logger in Loggers)
        {
            logger.Log(sample);
        }
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.HandleChannelUpdate
    public void HandleChannelUpdate(object sender, DataSample sample)
    {
        if (!Active || CurrentMode != LoggingMode.Stream || !_hasActiveApplicationSession)
        {
            return;
        }

        if (sample == null)
        {
            return;
        }

        _hasActiveApplicationSamples = true;
        sample.LoggingSessionID = Session.ID;

        // Log channel value to whatever loggers are being managed
        foreach (var logger in Loggers)
        {
            logger.Log(sample);
        }
    }

